<body>
  <main class="wrap">
    <header>
      <h1>Pocket Garden</h1>
      <p>Keep track of the plants you have put in the ground.</p>
      <p class="note">Choices reset when you reload the page.</p>
    </header>

    <div class="filters" role="group" aria-label="Filter plants by light">
      <button type="button" class="filter-btn" data-filter="all" aria-pressed="true">All plants</button>
      <button type="button" class="filter-btn" data-filter="sun" aria-pressed="false">Loves sun</button>
      <button type="button" class="filter-btn" data-filter="shade" aria-pressed="false">Likes shade</button>
    </div>

    <section class="grid" id="grid"></section>
  </main>

  <script>
    const plants = [
      {
        id: "basil",
        name: "Basil",
        light: "sun",
        description: "Warm, sunny spot with regular watering. Pinch off flowers to keep the leaves coming."
      },
      {
        id: "sunflower",
        name: "Sunflower",
        light: "sun",
        description: "Tall and bright. Give it full sun for most of the day."
      },
      {
        id: "mint",
        name: "Mint",
        light: "shade",
        description: "Vigorous spreader. Prefers shade and moist soil, so keep it in a pot if you can."
      }
    ];

    const lightLabels = { sun: "Loves sun", shade: "Likes shade" };

    const planted = new Set();
    const cards = new Map();
    const grid = document.getElementById("grid");
    const filterButtons = document.querySelectorAll(".filter-btn");

    function buildCard(plant) {
      const card = document.createElement("article");
      card.className = "card";

      const tag = document.createElement("span");
      tag.className = "tag " + plant.light;
      tag.textContent = lightLabels[plant.light];

      const title = document.createElement("h2");
      title.textContent = plant.name;

      const desc = document.createElement("p");
      desc.textContent = plant.description;

      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "plant-btn";
      btn.addEventListener("click", () => togglePlanted(plant.id));

      card.append(tag, title, desc, btn);
      grid.appendChild(card);
      cards.set(plant.id, { card, btn, plant });
    }

    function updateCard(id) {
      const { card, btn, plant } = cards.get(id);
      const isPlanted = planted.has(id);

      btn.textContent = isPlanted ? "Planted" : "Mark as planted";
      btn.setAttribute("aria-pressed", String(isPlanted));
      btn.setAttribute("aria-label", `${btn.textContent}: ${plant.name}`);
      card.classList.toggle("is-planted", isPlanted);
    }

    function togglePlanted(id) {
      if (planted.has(id)) {
        planted.delete(id);
      } else {
        planted.add(id);
      }
      updateCard(id);
    }

    function setFilter(filter) {
      filterButtons.forEach(button => {
        button.setAttribute("aria-pressed", String(button.dataset.filter === filter));
      });

      cards.forEach(({ card, plant }) => {
        card.hidden = !(filter === "all" || plant.light === filter);
      });
    }

    filterButtons.forEach(button => {
      button.addEventListener("click", () => setFilter(button.dataset.filter));
    });

    plants.forEach(buildCard);
    plants.forEach(plant => updateCard(plant.id));
    setFilter("all");
  </script>
</body>
